import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CircleGeometry,
    Color,
  } = THREE;

  const root = new Group();
  const timelines = [];
  const primitiveCleanups = [];
  const resources = [];
  let disposed = false;

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const trackTween = (target, vars) => {
    const tween = gsap.to(target, vars);
    timelines.push(tween);
    return tween;
  };

  const backdropGeometry = new PlaneGeometry(3.6, 2.8);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, uv().y),
  );
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -0.32);
  root.add(backdrop);

  const shadowGeometry = new CircleGeometry(1.28, 48);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.scale.set(1.0, 0.42, 1.0);
  shadow.position.set(0, -0.78, -0.08);
  root.add(shadow);

  const cardGeometry = new PlaneGeometry(2.45, 1.55);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.z = 0.02;
  root.add(card);

  const edgeGeometry = new PlaneGeometry(2.51, 1.61);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.16,
    depthWrite: false,
  });
  const accentEdge = new Mesh(edgeGeometry, edgeMaterial);
  accentEdge.position.z = -0.005;
  root.add(accentEdge);

  const innerGeometry = new PlaneGeometry(2.39, 1.49);
  const innerMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
  });
  const innerFrame = new Mesh(innerGeometry, innerMaterial);
  innerFrame.position.z = 0.005;
  root.add(innerFrame);
  root.remove(card);
  root.add(card);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string' || !ctx.fontAtlas) continue;
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 0.13,
      color: item.color ?? colors.paper,
      align: item.align ?? 'left',
      maxWidthPx: item.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx,
    });
    textObject.position.set(
      item.position?.[0] ?? -0.9,
      item.position?.[1] ?? -0.98,
      item.position?.[2] ?? 0.12,
    );
    root.add(textObject);
  }

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl && ctx.textureLoader?.loadTexture) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      resources.push(texture);
      cardMaterial.map = texture;
      cardMaterial.color.set(colors.paper);
      cardMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const factory = ctx.primitives?.[primitive.name];
    if (typeof factory !== 'function') continue;
    const result = factory(root, primitive.params);
    if (result?.timeline) timelines.push(result.timeline);
    if (typeof result?.cleanup === 'function') {
      primitiveCleanups.push(result.cleanup);
    }
  }

  const setHovered = (hovered) => {
    if (disposed) return;
    trackTween(root.position, {
      y: hovered ? 0.15 : 0,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: true,
    });
    trackTween(accentEdge.material, {
      opacity: hovered ? 0.42 : 0.16,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: true,
    });
  };

  const press = () => {
    if (disposed) return;
    const timeline = gsap.timeline();
    timelines.push(timeline);
    timeline
      .to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out',
      })
      .to(root.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.34,
        ease: 'back.out(2.2)',
      });
    ctx.emit?.('hub-journal.select', {
      node: config.id ?? 'journal-card-3',
    });
  };

  root.userData.handlers = {
    hover: (value = true) => setHovered(value !== false),
    pointerenter: () => setHovered(true),
    pointerleave: () => setHovered(false),
    click: press,
    focus: () => {
      trackTween(accentEdge.material, {
        opacity: 0.95,
        duration: 0.2,
        ease: 'power2.out',
        overwrite: true,
      });
    },
    blur: () => {
      trackTween(accentEdge.material, {
        opacity: 0.16,
        duration: 0.2,
        ease: 'power2.out',
        overwrite: true,
      });
    },
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }
    for (const cleanup of primitiveCleanups) {
      cleanup();
    }

    const geometries = [
      backdropGeometry,
      shadowGeometry,
      cardGeometry,
      edgeGeometry,
      innerGeometry,
    ];
    const materials = [
      backdropMaterial,
      shadowMaterial,
      cardMaterial,
      edgeMaterial,
      innerMaterial,
    ];

    for (const geometry of geometries) geometry.dispose?.();
    for (const material of materials) material.dispose?.();
    for (const resource of resources) resource.dispose?.();

    root.traverse((object) => {
      if (object !== root && object.userData?.cleanup) {
        object.userData.cleanup();
      }
    });
  };

  return root;
}
